1	import { ok, fail } from './result.js';
2	import { getCustomer } from './customers.js';
3	import { getProduct } from './catalogue.js';
4	import { nextInvoiceNumber } from './numbering.js';
5	
6	/**
7	 * Create a draft invoice.
8	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} invoice
9	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
10	 */
11	export function createInvoice({ customerId, issueDate, lines }) {
12	  // Validate customer exists
13	  const customerResult = getCustomer(customerId);
14	  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');
15	
16	  // Validate issueDate is a real date in YYYY-MM-DD format
17	  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) return fail('DATE_INVALID');
18	  const [year, month, day] = issueDate.split('-').map(Number);
19	  const date = new Date(Date.UTC(year, month - 1, day));
20	  if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) {
21	    return fail('DATE_INVALID');
22	  }
23	
24	  // Validate lines array is not empty
25	  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');
26	
27	  // Validate and build invoice lines
28	  const invoiceLines = [];
29	  for (const line of lines) {
30	    // Validate qty is a positive integer
31	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
32	
33	    // Validate SKU exists and get product details
34	    const productResult = getProduct(line.sku);
35	    if (!productResult.ok) return fail('UNKNOWN_SKU');
36	
37	    const product = productResult.value;
38	    invoiceLines.push({
39	      sku: line.sku,
40	      name: product.name,
41	      qty: line.qty,
42	      unitPrice: product.unitPrice,
43	      vatRate: product.vatRate,
44	    });
45	  }
46	
47	  return ok({
48	    customerId,
49	    issueDate,
50	    status: 'draft',
51	    lines: invoiceLines,
52	  });
53	}
54	
55	/**
56	 * Calculate the total for a single invoice line.
57	 * @param {{ qty: number, unitPrice: number }} line
58	 * @returns {number}
59	 */
60	export function lineTotal(line) {
61	  return line.qty * line.unitPrice;
62	}
63	
64	/**
65	 * Calculate invoice totals.
66	 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
67	 * @returns {{ subtotal: number, total: number }}
68	 */
69	export function invoiceTotals(invoice) {
70	  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
71	  return { subtotal, total: subtotal };
72	}
73	
74	/**
75	 * Add a line to a draft invoice, or increase qty if SKU already exists.
76	 * @param {{ status: string, lines: Array }} invoice
77	 * @param {{ sku: string, qty: number }} line
78	 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
79	 */
80	export function addLine(invoice, { sku, qty }) {
81	  // Check invoice is draft
82	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
83	
84	  // Validate qty is a positive integer
85	  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');
86	
87	  // Validate SKU exists and get product details
88	  const productResult = getProduct(sku);
89	  if (!productResult.ok) return fail('UNKNOWN_SKU');
90	
91	  const product = productResult.value;
92	
93	  // Check if SKU already exists on invoice
94	  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);
95	  let newLines;
96	
97	  if (existingLineIndex >= 0) {
98	    // Update qty of existing line
99	    newLines = invoice.lines.map((line, i) =>
100	      i === existingLineIndex ? { ...line, qty: line.qty + qty } : line
101	    );
102	  } else {
103	    // Add new line at the end
104	    newLines = [...invoice.lines, {
105	      sku,
106	      name: product.name,
107	      qty,
108	      unitPrice: product.unitPrice,
109	      vatRate: product.vatRate,
110	    }];
111	  }
112	
113	  return ok({
114	    ...invoice,
115	    lines: newLines,
116	  });
117	}
118	
119	/**
120	 * Remove a line from a draft invoice.
121	 * @param {{ status: string, lines: Array }} invoice
122	 * @param {string} sku
123	 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
124	 */
125	export function removeLine(invoice, sku) {
126	  // Check invoice is draft
127	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
128	
129	  // Check if line exists
130	  const lineExists = invoice.lines.some((line) => line.sku === sku);
