    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(
    addLine(r.value, { sku: 'INVALID-SKU', qty: 1 }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const original = r.value;
  addLine(original, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(original.lines.length, 1);
  assert.equal(original.lines[0].sku, 'DES-HOUR');
});

test('removeLine removes a line from the invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });
  const r2 = removeLine(r.value, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'COPY-HOUR');
});

test('removeLine returns NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2023-10-15',
    status: 'finalized',
    lines: [
      { sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'COPY-HOUR', qty: 2, name: 'Copywriting (hour)', unitPrice: 6000, vatRate: 21 },
    ],
  };
  assert.deepEqual(
    removeLine(invoice, 'DES-HOUR'),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('removeLine returns LINE_NOT_FOUND for unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(
    removeLine(r.value, 'COPY-HOUR'),
    { ok: false, error: 'LINE_NOT_FOUND' }
  );
});

test('removeLine returns NO_LINES if it would remove the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(
    removeLine(r.value, 'DES-HOUR'),
    { ok: false, error: 'NO_LINES' }
  );
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });
  const original = r.value;
  removeLine(original, 'COPY-HOUR');
  assert.equal(original.lines.length, 2);
  assert.equal(original.lines[1].sku, 'COPY-HOUR');
});

test('addLine and removeLine work together', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'COPY-HOUR', qty: 2 });
  const r3 = addLine(r2.value, { sku: 'ICON-SET', qty: 3 });
  const r4 = removeLine(r3.value, 'COPY-HOUR');
  assert.equal(r4.ok, true);
  assert.equal(r4.value.lines.length, 2);
  assert.equal(r4.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r4.value.lines[1].sku, 'ICON-SET');
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.number, 'INV-2023-0001');
});

test('issueInvoice assigns the next available number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
