  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2024-0001');
});

test('issueInvoice returns NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2023-10-15',
    status: 'issued',
    number: 'INV-2023-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(
    issueInvoice(invoice, []),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('issueInvoice preserves all invoice data', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.value.customerId, 'C-001');
  assert.equal(r2.value.issueDate, '2023-10-15');
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].qty, 5);
  assert.equal(r2.value.lines[1].qty, 2);
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const original = r.value;
  issueInvoice(original, []);
  assert.equal(original.status, 'draft');
  assert.ok(!original.number);
});

